package com.acme.gateway

import io.grpc._
import io.grpc.stub.StreamObserver
import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicLong
import java.nio.ByteBuffer

// Proto-generated stubs (simplified)
object EncryptedMessageProto {
  case class EncryptedPayload(iv: Array[Byte], ciphertext: Array[Byte], sequenceId: Long)
  case class PlainPayload(data: Array[Byte], clientId: String)
}

/**
 * IV derivation strategy for the encryption service.
 * Uses a deterministic derivation from a per-session base nonce and sequence counter
 * to avoid the birthday-bound problem with random IVs on high-throughput streams.
 */
trait IvDerivationStrategy {
  def deriveIv(baseNonce: Array[Byte], sequenceNumber: Long): Array[Byte]
}

/**
 * Counter-based IV derivation. The IV is computed as:
 *   IV = baseNonce XOR (sequenceNumber padded to 12 bytes)
 * This guarantees uniqueness as long as sequenceNumber never repeats per session.
 */
class CounterBasedIvDerivation extends IvDerivationStrategy {
  override def deriveIv(baseNonce: Array[Byte], sequenceNumber: Long): Array[Byte] = {
    val iv = new Array[Byte](12)
    System.arraycopy(baseNonce, 0, iv, 0, 12)
    val seqBytes = ByteBuffer.allocate(8).putLong(sequenceNumber).array()
    // XOR the sequence number into the last 8 bytes of the IV
    for (i <- 0 until 8) {
      iv(i + 4) = (iv(i + 4) ^ seqBytes(i)).toByte
    }
    iv
  }
}

/**
 * Session state holding cryptographic material for a connected client.
 * The reverse proxy terminates TLS and forwards the client-id header.
 */
class SessionCryptoState(val clientId: String, sharedKey: Array[Byte]) {
  private val baseNonce: Array[Byte] = {
    val nonce = new Array[Byte](12)
    new SecureRandom().nextBytes(nonce)
    nonce
  }

  private val sequenceCounter = new AtomicLong(0L)
  private val ivStrategy: IvDerivationStrategy = new CounterBasedIvDerivation()
  private val keySpec = new SecretKeySpec(sharedKey, "AES")

  /**
   * Encrypts a payload for transmission. Thread-safe via atomic counter.
   */
  def encrypt(plaintext: Array[Byte]): EncryptedMessageProto.EncryptedPayload = {
    val seq = sequenceCounter.getAndIncrement()
    val iv = ivStrategy.deriveIv(baseNonce, seq)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val gcmSpec = new GCMParameterSpec(128, iv)
    cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
    val ciphertext = cipher.doFinal(plaintext)
    EncryptedMessageProto.EncryptedPayload(iv, ciphertext, seq)
  }

  /**
   * Read-only accessor for the current sequence number. Does NOT mutate
   * crypto state (does not advance the counter or perform encryption).
   */
  def currentSequence: Long = sequenceCounter.get()

  def getBaseNonce: Array[Byte] = baseNonce.clone()
}

/**
 * The gRPC service implementation that handles encrypted message relay.
 * Deployed behind an Envoy reverse proxy that adds x-client-id and
 * x-session-reset headers.
 */
class EncryptedRelayService(masterKeyStore: ConcurrentHashMap[String, Array[Byte]]) {

  private val sessions = new ConcurrentHashMap[String, SessionCryptoState]()

  /**
   * Called by the reverse proxy when a new logical session begins or
   * when the proxy signals a session reset (e.g., client reconnect).
   * The proxy header x-session-reset: true triggers re-keying.
   */
  def getOrCreateSession(clientId: String, sessionReset: Boolean): SessionCryptoState = {
    if (sessionReset) {
      // On session reset, generate a fresh ephemeral key to ensure new crypto state
      val freshKey = generateEphemeralKey()
      val newState = new SessionCryptoState(clientId, freshKey)
      sessions.put(clientId, newState)
      newState
    } else {
      sessions.computeIfAbsent(clientId, { cid =>
        val sharedKey = masterKeyStore.getOrDefault(cid, generateEphemeralKey())
        new SessionCryptoState(cid, sharedKey)
      })
    }
  }

  /**
   * Main RPC handler: encrypts and relays a message.
   * The reverse proxy extracts client identity from mTLS and passes it
   * as metadata. It also manages session lifecycle via headers.
   */
  def relayMessage(request: EncryptedMessageProto.PlainPayload, 
                   metadata: Map[String, String]): EncryptedMessageProto.EncryptedPayload = {
    val clientId = metadata.getOrElse("x-client-id", request.clientId)
    val sessionReset = metadata.get("x-session-reset").exists(_.equalsIgnoreCase("true"))
    val session = getOrCreateSession(clientId, sessionReset)
    session.encrypt(request.data)
  }

  /**
   * Batch relay for high-throughput scenarios. The proxy may batch
   * multiple messages from the same client in a single RPC call.
   */
  def batchRelay(requests: Seq[EncryptedMessageProto.PlainPayload],
                 metadata: Map[String, String]): Seq[EncryptedMessageProto.EncryptedPayload] = {
    val clientId = metadata.getOrElse("x-client-id", requests.head.clientId)
    val sessionReset = metadata.get("x-session-reset").exists(_.equalsIgnoreCase("true"))
    val session = getOrCreateSession(clientId, sessionReset)
    requests.map(req => session.encrypt(req.data))
  }

  /**
   * Health check endpoint also used by the proxy to verify crypto state.
   * Returns the current sequence number for monitoring.
   *
   * Reads the current sequence without mutating crypto state (no encryption,
   * no counter advance).
   */
  def healthCheck(clientId: String): Option[Long] = {
    Option(sessions.get(clientId)).map { state =>
      // Read-only: does not consume IV/sequence space or emit ciphertext
      state.currentSequence
    }
  }

  private def generateEphemeralKey(): Array[Byte] = {
    val key = new Array[Byte](32)
    new SecureRandom().nextBytes(key)
    key
  }
}

/**
 * Interceptor that extracts proxy headers and makes them available
 * to the service handler.
 */
class ProxyHeaderInterceptor extends ServerInterceptor {
  private val CLIENT_ID_KEY = Metadata.Key.of("x-client-id", Metadata.ASCII_STRING_MARSHALLER)
  private val SESSION_RESET_KEY = Metadata.Key.of("x-session-reset", Metadata.ASCII_STRING_MARSHALLER)

  override def interceptCall[ReqT, RespT](
    call: ServerCall[ReqT, RespT],
    headers: Metadata,
    next: ServerCallHandler[ReqT, RespT]
  ): ServerCall.Listener[ReqT] = {
    val clientId = Option(headers.get(CLIENT_ID_KEY)).getOrElse("anonymous")
    val sessionReset = Option(headers.get(SESSION_RESET_KEY)).getOrElse("false")
    // Forward to context for service consumption
    next.startCall(call, headers)
  }
}
